widget.solution:
import numpy as np

def simulate_ar1(phi, n, seed):
    e = np.random.default_rng(seed).standard_normal(n)
    x = np.empty(n)
    x[0] = e[0]
    for t in range(1, n):
        x[t] = phi * x[t - 1] + e[t]
    return x

def variance_of_ar1(phi, sigma):
    return sigma ** 2 / (1 - phi ** 2)
